    StringSample("Strings.App.Errors.authProxy(status: 0)", { Strings.App.Errors.authProxy(status: 0) }, en: "An access proxy answered HTTP 0 before the gateway did. Add its headers under Advanced, or exempt /api/status, /auth/* and /login from it.", nl: "Een access proxy antwoordde met HTTP 0 vóór de gateway. Voeg zijn headers toe onder Geavanceerd, of sluit /api/status, /auth/* en /login ervan uit.", de: "Ein Access-Proxy hat mit HTTP 0 geantwortet, bevor das Gateway dran war. Füge seine Header unter Erweitert hinzu, oder nimm /api/status, /auth/* und /login davon aus."),
