    StringSample("Strings.App.Errors.closeChatOff", { Strings.App.Errors.closeChatOff }, en: "Chat is switched off on this gateway.", nl: "Chat staat uit op deze gateway.", de: "Chat ist auf diesem Gateway abgeschaltet."),
    StringSample("Strings.App.Errors.closeHost", { Strings.App.Errors.closeHost }, en: "The gateway does not trust this address. Set its `dashboard.public_url` to the address you entered and restart it.", nl: "De gateway vertrouwt dit adres niet. Zet zijn `dashboard.public_url` op het adres dat je hebt ingevuld en start hem opnieuw.", de: "Das Gateway traut dieser Adresse nicht. Setze sein `dashboard.public_url` auf die Adresse, die du eingegeben hast, und starte es neu."),
    StringSample("Strings.App.Errors.closeTakenOver", { Strings.App.Errors.closeTakenOver }, en: "Another client took this connection over. Close the other client and test again.", nl: "Een andere client heeft deze verbinding overgenomen. Sluit die client en test opnieuw.", de: "Ein anderer Client hat diese Verbindung übernommen. Schließe den anderen Client und teste erneut."),
    StringSample("Strings.App.Errors.incompatible", { Strings.App.Errors.incompatible }, en: "This gateway is too old for Hermie. Update Hermes on the gateway.", nl: "Deze gateway is te oud voor Hermie. Werk Hermes op de gateway bij.", de: "Dieses Gateway ist zu alt für Hermie. Aktualisiere Hermes auf dem Gateway."),
    StringSample("Strings.App.Errors.landingPage", { Strings.App.Errors.landingPage }, en: "This looks like a web page, not a gateway.", nl: "Dit lijkt een webpagina, geen gateway.", de: "Das sieht nach einer Webseite aus, nicht nach einem Gateway."),
