    StringSample("Strings.App.Errors.network(host: \"x {y} 100% %@\")", { Strings.App.Errors.network(host: "x {y} 100% %@") }, en: "Could not reach x {y} 100% %@. Check the address, and that the gateway is running and reachable from this device.", nl: "x {y} 100% %@ kon niet worden bereikt. Controleer het adres, en of de gateway draait en vanaf dit apparaat bereikbaar is.", de: "x {y} 100% %@ war nicht erreichbar. Prüfe die Adresse und ob das Gateway läuft und von diesem Gerät aus erreichbar ist."),
    StringSample("Strings.App.Errors.networkOverHttps(host: \"Ada\")", { Strings.App.Errors.networkOverHttps(host: "Ada") }, en: "Could not reach Ada over https://. It is either not answering there, or serving a certificate this device does not trust. Leave the https:// off and Hermie will try http:// as well.", nl: "Ada kon niet via https:// worden bereikt. Hij antwoordt daar niet, of hij levert een certificaat dat dit apparaat niet vertrouwt. Laat de https:// weg en Hermie probeert ook http://.", de: "Ada war über https:// nicht erreichbar. Entweder antwortet es dort nicht, oder es liefert ein Zertifikat, dem dieses Gerät nicht traut. Lass das https:// weg, dann versucht Hermie auch http://."),
