    StringSample("Strings.App.Onboarding.Address.FrontDoor.cloudflareHint", { Strings.App.Onboarding.Address.FrontDoor.cloudflareHint }, en: "A service token from your Access application. Hermie sends it with every request, the WebSocket and the sign-in page. Exempt /auth/* and /login from the Access policy: a service token cannot carry a redirect-based sign-in through the edge.", nl: "Een service token uit je Access-applicatie. Hermie stuurt hem mee met elke request, met de WebSocket en met de inlogpagina. Sluit /auth/* en /login uit van het Access-beleid: een service token kan een inlog met redirects niet door de edge heen dragen.", de: "Ein Service-Token aus deiner Access-Anwendung. Hermie sendet es mit jedem Request, mit dem WebSocket und mit der Anmeldeseite. Nimm /auth/* und /login von der Access-Policy aus: Ein Service-Token kann eine weiterleitungsbasierte Anmeldung nicht durch die Edge tragen."),
    StringSample("Strings.App.Onboarding.Address.FrontDoor.custom", { Strings.App.Onboarding.Address.FrontDoor.custom }, en: "Custom headers", nl: "Eigen headers", de: "Eigene Header"),
    StringSample("Strings.App.Onboarding.Address.FrontDoor.hint", { Strings.App.Onboarding.Address.FrontDoor.hint }, en: "Pick how the proxy in front of your gateway lets Hermie through. Nothing here is sent anywhere but the gateway’s own address.", nl: "Kies hoe de proxy vóór je gateway Hermie doorlaat. Niets hiervan gaat ergens anders heen dan naar het adres van de gateway zelf.", de: "Wähle, wie der Proxy vor deinem Gateway Hermie durchlässt. Nichts davon wird irgendwohin gesendet außer an die Adresse des Gateways selbst."),
    StringSample("Strings.App.Onboarding.Address.FrontDoor.insecure", { Strings.App.Onboarding.Address.FrontDoor.insecure }, en: "This gateway is reached over http://, so the service token is not being sent — it is a long-lived credential for your whole Access tenant. Use https:// for the address the Access application covers.", nl: "Deze gateway wordt via http:// bereikt, dus het service token wordt niet meegestuurd — het is een langlevende credential voor je hele Access-tenant. Gebruik https:// voor het adres dat de Access-applicatie dekt.", de: "Dieses Gateway wird über http:// erreicht, deshalb wird das Service-Token nicht gesendet — es ist ein langlebiges Credential für deinen gesamten Access-Tenant. Nutze https:// für die Adresse, die die Access-Anwendung abdeckt."),
    StringSample("Strings.App.Onboarding.Address.FrontDoor.label", { Strings.App.Onboarding.Address.FrontDoor.label }, en: "IN FRONT OF THE GATEWAY", nl: "VOOR DE GATEWAY", de: "VOR DEM GATEWAY"),
