    StringSample("Strings.App.Onboarding.SignIn.ssoOff", { Strings.App.Onboarding.SignIn.ssoOff }, en: "Sign-in with SSO is turned off on this Hermie Web. Ask whoever runs it to sign you in another way.", nl: "Inloggen via SSO staat uit op deze Hermie Web. Vraag degene die hem beheert om je op een andere manier in te loggen.", de: "Die Anmeldung per SSO ist auf diesem Hermie Web ausgeschaltet. Bitte denjenigen, der es betreibt, dich auf einem anderen Weg anzumelden."),
    StringSample("Strings.App.Onboarding.SignIn.subtitleCookie", { Strings.App.Onboarding.SignIn.subtitleCookie }, en: "The gateway hosts the sign-in page. Your browser keeps the session it hands back; Hermie never sees it.", nl: "De gateway host de inlogpagina. Je browser bewaart de sessie die hij teruggeeft; Hermie ziet die nooit.", de: "Das Gateway hostet die Anmeldeseite. Dein Browser behält die Session, die sie zurückgibt; Hermie bekommt sie nie zu sehen."),
    StringSample("Strings.App.Onboarding.SignIn.subtitleNative", { Strings.App.Onboarding.SignIn.subtitleNative }, en: "The gateway hosts the sign-in page. Hermie opens it, reads the result and keeps the tokens on this device.", nl: "De gateway host de inlogpagina. Hermie opent die, leest het resultaat en bewaart de tokens op dit apparaat.", de: "Das Gateway hostet die Anmeldeseite. Hermie öffnet sie, liest das Ergebnis und behält die Token auf diesem Gerät."),
    StringSample("Strings.App.Onboarding.SignIn.subtitleToken", { Strings.App.Onboarding.SignIn.subtitleToken }, en: "This gateway is not gated by an identity provider; it authenticates with the session token it prints at startup.", nl: "Deze gateway zit niet achter een identity provider; hij authenticeert met het session token dat hij bij het starten afdrukt.", de: "Dieses Gateway steht nicht hinter einem Identity Provider; es authentifiziert sich mit dem Session-Token, das es beim Start ausgibt."),
    StringSample("Strings.App.Onboarding.SignIn.title", { Strings.App.Onboarding.SignIn.title }, en: "Sign in", nl: "Inloggen", de: "Anmelden"),
    StringSample("Strings.App.Onboarding.SignIn.tokenBlockedBody", { Strings.App.Onboarding.SignIn.tokenBlockedBody }, en: "It authenticates with a session token, and a browser tab has nowhere safe to keep one — anything running in the page could read it. Use the Hermie app, or put the gateway behind an identity provider so it can issue a browser session.", nl: "Hij authenticeert met een session token, en een browsertab heeft geen veilige plek om er een te bewaren — alles wat in de pagina draait zou het kunnen lezen. Gebruik de Hermie-app, of zet de gateway achter een identity provider zodat hij een browsersessie kan uitgeven.", de: "Es authentifiziert sich mit einem Session-Token, und ein Browser-Tab hat keinen sicheren Ort dafür — alles, was auf der Seite läuft, könnte es lesen. Nutze die Hermie-App, oder stelle das Gateway hinter einen Identity Provider, damit es eine Browser-Session ausstellen kann."),
    StringSample("Strings.App.Onboarding.SignIn.tokenBlockedTitle", { Strings.App.Onboarding.SignIn.tokenBlockedTitle }, en: "This gateway cannot be used from a browser", nl: "Deze gateway is niet vanuit een browser te gebruiken", de: "Dieses Gateway lässt sich aus einem Browser nicht nutzen"),
    StringSample("Strings.App.Onboarding.SignIn.tokenHelp", { Strings.App.Onboarding.SignIn.tokenHelp }, en: "Paste the session token printed by `hermes serve`.", nl: "Plak het session token dat `hermes serve` afdrukt.", de: "Füge das Session-Token ein, das `hermes serve` ausgibt."),
    StringSample("Strings.App.Onboarding.SignIn.tokenLabel", { Strings.App.Onboarding.SignIn.tokenLabel }, en: "SESSION TOKEN", nl: "SESSION TOKEN", de: "SESSION-TOKEN"),
    StringSample("Strings.App.Onboarding.SignIn.tokenPlaceholder", { Strings.App.Onboarding.SignIn.tokenPlaceholder }, en: "Session token", nl: "Session token", de: "Session-Token"),
    StringSample("Strings.App.Onboarding.SignIn.Webview.cancelled", { Strings.App.Onboarding.SignIn.Webview.cancelled }, en: "Sign-in was cancelled.", nl: "Het inloggen is geannuleerd.", de: "Die Anmeldung wurde abgebrochen."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.chosen", { Strings.App.Onboarding.SignIn.Webview.chosen }, en: "Open the sign-in page in your browser, then paste the address it fails to open back here. You can go back and use the in-app page instead.", nl: "Open de inlogpagina in je browser en plak het adres dat hij niet kan openen hier terug. Je kunt ook terug en alsnog de in-app pagina gebruiken.", de: "Öffne die Anmeldeseite in deinem Browser und füge dann die Adresse, an der er scheitert, hier wieder ein. Du kannst zurückgehen und stattdessen die In-App-Seite nutzen."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.exchanging", { Strings.App.Onboarding.SignIn.Webview.exchanging }, en: "Completing sign-in…", nl: "Inloggen afronden…", de: "Schließe die Anmeldung ab…"),
    StringSample("Strings.App.Onboarding.SignIn.Webview.fallbackHelp", { Strings.App.Onboarding.SignIn.Webview.fallbackHelp }, en: "The browser will fail to load a 127.0.0.1 address — that is expected. Copy it out of the address bar and paste it here.", nl: "De browser zal een 127.0.0.1-adres niet kunnen laden — dat hoort zo. Kopieer het uit de adresbalk en plak het hier.", de: "Der Browser wird eine 127.0.0.1-Adresse nicht laden können — das ist so gewollt. Kopiere sie aus der Adressleiste und füge sie hier ein."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.fallbackLabel", { Strings.App.Onboarding.SignIn.Webview.fallbackLabel }, en: "Failed address", nl: "Mislukt adres", de: "Gescheiterte Adresse"),
    StringSample("Strings.App.Onboarding.SignIn.Webview.fallbackPlaceholder", { Strings.App.Onboarding.SignIn.Webview.fallbackPlaceholder }, en: "http://127.0.0.1:38007/callback?code=…", nl: "http://127.0.0.1:38007/callback?code=…", de: "http://127.0.0.1:38007/callback?code=…"),
    StringSample("Strings.App.Onboarding.SignIn.Webview.fallbackSubmit", { Strings.App.Onboarding.SignIn.Webview.fallbackSubmit }, en: "Use this address", nl: "Dit adres gebruiken", de: "Diese Adresse verwenden"),
    StringSample("Strings.App.Onboarding.SignIn.Webview.headersWithheld", { Strings.App.Onboarding.SignIn.Webview.headersWithheld }, en: "This gateway needs extra headers, and Android’s in-app browser would forward them to your identity provider. Sign in in your browser instead, then paste the address it fails to open back here.", nl: "Deze gateway heeft extra headers nodig, en de in-app browser van Android zou die doorsturen naar je identity provider. Log in je browser in en plak het adres dat hij niet kan openen hier terug.", de: "Dieses Gateway braucht zusätzliche Header, und Androids In-App-Browser würde sie an deinen Identity Provider weiterreichen. Melde dich stattdessen in deinem Browser an und füge dann die Adresse, an der er scheitert, hier wieder ein."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.httpError(status: 0)", { Strings.App.Onboarding.SignIn.Webview.httpError(status: 0) }, en: "The sign-in page answered HTTP 0. Check the gateway's public address.", nl: "De inlogpagina antwoordde met HTTP 0. Controleer het publieke adres van de gateway.", de: "Die Anmeldeseite hat mit HTTP 0 geantwortet. Prüfe die öffentliche Adresse des Gateways."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.httpError(status: 1)", { Strings.App.Onboarding.SignIn.Webview.httpError(status: 1) }, en: "The sign-in page answered HTTP 1. Check the gateway's public address.", nl: "De inlogpagina antwoordde met HTTP 1. Controleer het publieke adres van de gateway.", de: "Die Anmeldeseite hat mit HTTP 1 geantwortet. Prüfe die öffentliche Adresse des Gateways."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.httpError(status: 2)", { Strings.App.Onboarding.SignIn.Webview.httpError(status: 2) }, en: "The sign-in page answered HTTP 2. Check the gateway's public address.", nl: "De inlogpagina antwoordde met HTTP 2. Controleer het publieke adres van de gateway.", de: "Die Anmeldeseite hat mit HTTP 2 geantwortet. Prüfe die öffentliche Adresse des Gateways."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.httpError(status: 5)", { Strings.App.Onboarding.SignIn.Webview.httpError(status: 5) }, en: "The sign-in page answered HTTP 5. Check the gateway's public address.", nl: "De inlogpagina antwoordde met HTTP 5. Controleer het publieke adres van de gateway.", de: "Die Anmeldeseite hat mit HTTP 5 geantwortet. Prüfe die öffentliche Adresse des Gateways."),
    StringSample("Strings.App.Onboarding.SignIn.Webview.httpError(status: 21)", { Strings.App.Onboarding.SignIn.Webview.httpError(status: 21) }, en: "The sign-in page answered HTTP 21. Check the gateway's public address.", nl: "De inlogpagina antwoordde met HTTP 21. Controleer het publieke adres van de gateway.", de: "Die Anmeldeseite hat mit HTTP 21 geantwortet. Prüfe die öffentliche Adresse des Gateways."),
