    StringSample("Strings.App.Onboarding.SignIn.Webview.timeout", { Strings.App.Onboarding.SignIn.Webview.timeout }, en: "The sign-in page was open for ten minutes without finishing. Start again when you are ready.", nl: "De inlogpagina stond tien minuten open zonder af te ronden. Begin opnieuw wanneer je zover bent.", de: "Die Anmeldeseite war zehn Minuten offen, ohne fertig zu werden. Fang neu an, wenn du so weit bist."),
